INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 15, 'theory', 'Quiz: pipes, shared memory, and sockets');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 15, 0, 'What does a pipe reader get when all write descriptors are closed?', '["An EPIPE error", "A SIGPIPE signal", "It will wait forever", "End of file: read returns 0"]', 3, 'Zero bytes is the sign of end of stream. That is exactly why it is important to close unused pipe ends.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 15, 1, 'What does a writer get if a pipe has no readers at all?', '["The data goes to disk", "A SIGPIPE signal, or if it is ignored, an EPIPE error", "The write will wait for a reader forever", "The kernel silently drops the data"]', 1, 'This is how a pipeline ends when the next program has finished reading: head stops yes.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 15, 2, 'How does a named pipe (FIFO) differ from an anonymous one?', '["It has a name in the filesystem, so it connects unrelated processes", "It stores data on disk", "It works only in both directions", "It is faster because it does not use the kernel"]', 0, 'The mechanism is the same: a buffer in the kernel. But an anonymous pipe is shared only through inheriting descriptors.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 15, 3, 'What can a Unix domain socket do that an ordinary pipe cannot?', '["Carry data between different computers", "Keep messages after a reboot", "Pass open file descriptors and report the identity of the connecting process", "Work without the kernel"]', 2, 'Descriptor passing goes through an SCM_RIGHTS message, and information about the peer through SO_PEERCRED.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 15, 4, 'Why is shared memory faster than pipes?', '["The kernel compresses the data", "Data is not copied through the kernel: both sides see the same physical page", "The memory sits on a faster disk", "Shared memory does not use page tables"]', 1, 'The price of speed is manual synchronization: the kernel does not control access order.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 15, 5, 'What does a futex do when the lock is free?', '["Calls the kernel to record the owner", "Blocks all other threads", "Disables interrupts", "Takes it with an atomic operation in user space, with no system call"]', 3, 'The kernel gets involved only on contention: to put a waiter to sleep and wake it on release.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 15, 6, 'Why can''t you call printf in a signal handler?', '["printf is forbidden by the standard at all stages of execution", "The handler runs in kernel mode", "The handler interrupts the program at any point, and printf is not reentrant; only async-signal-safe functions are allowed", "printf is too slow"]', 2, 'If the signal interrupted malloc or printf, reentering them can corrupt their internal state. It is safe, for example, to write a byte into a pipe.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 15, 7, 'Which communication method fits for passing an open file descriptor to a neighboring process?', '["A Unix domain socket: a message with SCM_RIGHTS", "An anonymous pipe", "Shared memory", "The SIGUSR1 signal"]', 0, 'The receiver gets a new descriptor for the same open file description, as if it had called dup itself.');
